// The slice of node-postgres the fixture code touches. The recognizer
// settles a query by where `query` is declared, so the declarations
// have to be on disk under node_modules.

export interface QueryResult<Row = unknown> {
  rows: Row[];
  rowCount: number;
}

export class Pool {
  constructor(config?: { connectionString?: string });
  query<Row = unknown>(
    text: string,
    values?: unknown[],
  ): Promise<QueryResult<Row>>;
  end(): Promise<void>;
}
